#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int scores[] = {3, 6, 9};
    int target = 9;
    int checks = 0;
    for (int i = 0; i < 3; i++) {
        checks++;
        if (scores[i] == target) break;
    }
    printf("%d\n", checks);
    return 0;
}

#include <iostream>

int main() {
    int scores[] = {3, 6, 9};
    int target = 9;
    int checks = 0;
    for (int score : scores) {
        checks++;
        if (score == target) break;
    }
    std::cout << checks << '\n';
    return 0;
}

int[] scores = { 3, 6, 9 };
int target = 9;
int checks = 0;
foreach (int score in scores)
{
    checks++;
    if (score == target) break;
}
System.Console.WriteLine(checks);

public class Main {
    public static void main(String[] args) {
        int[] scores = {3, 6, 9};
        int target = 9;
        int checks = 0;
        for (int score : scores) {
            checks++;
            if (score == target) break;
        }
        System.out.println(checks);
    }
}
